def shell(title, readout, body):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)}</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Newsreader:opsz,wght@6..72,400;6..72,500;6..72,600&family=Plus+Jakarta+Sans:wght@400;500;600;700&display=swap" rel="stylesheet"><style>{CSS}</style></head><body><main><header>{logo()}<h1>{html.escape(title)}</h1><div class="date">{DATE} · adaptive daily ingest</div><p class="muted">{readout}</p></header>{body}</main></body></html>'''

def card(item):
    return f'''<article class="card" id="{item['id']}"><h2>{html.escape(item['title'])}</h2><div class="badges"><span class="badge {item.get('badge','good')}">{item.get('badge_text','fresh signal')}</span><span class="badge">{html.escape(item['type'])}</span></div><ul class="facts"><li>Source: <a href="{item['url']}">{html.escape(item['source'])}</a></li><li>Published / updated: {item['date']}</li></ul><p><strong>What it is:</strong> {item['what']}</p><p><strong>Why it matters:</strong> {item['why']}</p><p><strong>Buildn / client use:</strong> {item['use']}</p><p><strong>Why useful now:</strong> {item['now']}</p><div class="callout"><strong>Caveat:</strong> {item['caveat']}</div><ul class="wins"><li><strong>Next:</strong> {item['action']}</li></ul></article>'''

def lane_report(slug,title,readout,diagram,items, rationale):
    matrix=''.join(f'<tr><th>{html.escape(row[0])}</th><td>{row[1]}</td><td>{row[2]}</td><td>{row[3]}</td></tr>' for row in [
        ('Buildn OS','Expose the control seam in artifacts.','Trial as a reusable packet.','Keep provenance attached.'),
        ('Client work','Turn the signal into a design or delivery review.','Offer a bounded pilot.','Name the adoption metric.'),
        ('Agent workflows','Add a checkpoint, typed tool, or test.','Measure latency and failure.','Keep a human escape hatch.'),
        ('Personal leverage','Open the primary source first.','Spend 30 minutes hands-on.','Write one reusable note.')])
    body=f'''<section><article class="card"><h2>Executive readout</h2><div class="badges"><span class="badge good">selected lane</span><span class="badge">{html.escape(rationale)}</span></div><div class="diagram">{diagram}</div><p>{readout}</p></article></section><section><h2>Dossier cards</h2>{''.join(card(x) for x in items)}</section><section><article class="card"><h2>Use-case matrix</h2><table class="matrix"><thead><tr><th>Surface</th><th>Buildn OS</th><th>Client work</th><th>Agent workflow</th></tr></thead><tbody>{matrix}</tbody></table></article></section><section><article class="card topline"><h2>Top actions</h2><ol class="wins"><li>Open the first two primary sources and capture the control or workflow primitive.</li><li>Run one bounded proof-of-concept with an explicit human checkpoint.</li><li>Record what changed in the ledger before adopting the pattern elsewhere.</li></ol></article></section><section><article class="card"><h2>Source trail</h2><ol class="source-trail">{''.join(f'<li><a href="{x["url"]}">{html.escape(x["source"])}</a></li>' for x in items)}</ol></article></section>'''
    return shell(f'Daily Ingest Dossier — {title}',readout,body)

