# Overview/index: own readout, rationale, links, and top three.
links=''.join(f'<li><a href="{slug}.html">{html.escape(lane["title"])}</a> — {html.escape(lane["rationale"])}</li>' for slug,lane in lanes.items())
overview_body=f'''<section><article class="card"><h2>Executive readout</h2><p>{ledger['editorial_thesis']}</p><div class="diagram"><svg viewBox="0 0 720 130" role="img" aria-label="Four lanes converge on inspectable delivery"><rect x="20" y="20" width="145" height="36" rx="6" fill="#ecfdf5" stroke="#01dc82"/><text x="92" y="43" text-anchor="middle" class="label">orchestration</text><rect x="190" y="20" width="145" height="36" rx="6" fill="#ecfdf5" stroke="#01dc82"/><text x="262" y="43" text-anchor="middle" class="label">design context</text><rect x="360" y="20" width="145" height="36" rx="6" fill="#fef3c7" stroke="#9a6700"/><text x="432" y="43" text-anchor="middle" class="label">identity</text><rect x="530" y="20" width="165" height="36" rx="6" fill="#ecfdf5" stroke="#01dc82"/><text x="612" y="43" text-anchor="middle" class="label">embodied loops</text><line x1="360" y1="56" x2="360" y2="92" stroke="#94a3b8"/><line x1="92" y1="56" x2="360" y2="92" stroke="#94a3b8"/><line x1="262" y1="56" x2="360" y2="92" stroke="#94a3b8"/><line x1="432" y1="56" x2="360" y2="92" stroke="#94a3b8"/><line x1="612" y1="56" x2="360" y2="92" stroke="#94a3b8"/><rect x="280" y="92" width="160" height="26" rx="6" fill="#033330"/><text x="360" y="110" text-anchor="middle" class="label" fill="#fff">inspectable delivery</text></svg></div></article></section><section><article class="card"><h2>Selected lanes</h2><ul>{links}</ul></article></section><section><article class="card topline"><h2>Top three today</h2><ol class="wins"><li><strong>Dynamic workflows:</strong> turn recurring agent work into versioned, checkpointed orchestration.</li><li><strong>Design-system context:</strong> make the handoff seam itself agent-readable.</li><li><strong>Agent identity:</strong> audit defaults, scopes, and revocation before adding autonomy.</li></ol></article></section><section><article class="card"><h2>Archive and source trail</h2><p>All four lane dossiers are linked above and each includes direct primary URLs, caveats, and next actions. This run intentionally rotates away from yesterday’s exact themes while preserving infrastructure and security as practical threads.</p></article></section>'''
overview=shell('Daily Ingest Dossier — Overview',ledger['editorial_thesis'],overview_body)
(OUT/f'daily-ingest-overview-{DATE.replace("-","")}.html').write_text(overview,encoding='utf-8')
(OUT/f'daily-ingest-{DATE.replace("-","")}.json').write_text(json.dumps(ledger,indent=2,ensure_ascii=False),encoding='utf-8')

# Update local rolling ledger with last 45 days of item detail and durable theme summary.
coverage=Path('/root/Projects/daily-ingest-pages/topic-coverage.json')
if coverage.exists(): data=json.loads(coverage.read_text())
else: data={'schema_version':1,'initialized_at':STAMP,'purpose':'Rolling coverage memory for adaptive daily ingest.','rolling_theme_summary':{},'item_history':[]}
summary=data.setdefault('rolling_theme_summary',{})
for slug,lane in lanes.items():
    entry=summary.setdefault(slug,{'title':lane['title'],'times_covered':0,'last_covered':None})
    entry['title']=lane['title']; entry['times_covered']=entry.get('times_covered',0)+1; entry['last_covered']=DATE
history=data.setdefault('item_history',[])
for slug,lane in lanes.items():
    history.append({'date':DATE,'topic':slug,'title':lane['title'],'items':[{'title':x['title'],'url':x['url'],'source_type':x['type']} for x in lane['items']],'selection_rationale':lane['rationale']})
data['item_history']=[x for x in history if x.get('date','') >= '2026-09-12']
data['updated_at']=STAMP
coverage.write_text(json.dumps(data,indent=2,ensure_ascii=False),encoding='utf-8')
print('generated',len(lanes)+2,'artifacts in',OUT)
